import gspmv = require( './index' );


// TESTS //

// The function returns an array...
{
	const x = new Float64Array( 10 );
	const y = new Float64Array( 10 );
	const AP = new Float64Array( 55 );

	gspmv( 'row-major', 'upper', 10, 1.0, AP, x, 1, 1.0, y, 1 ); // $ExpectType Float64Array
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const x = new Float64Array( 10 );
	const y = new Float64Array( 10 );
	const AP = new Float64Array( 55 );

	gspmv( 10, 'upper', 10, 1.0, AP, x, 1, 1.0, y, 1 ); // $ExpectError
	gspmv( true, 'upper', 10, 1.0, AP, x, 1, 1.0, y, 1 ); // $ExpectError
	gspmv( false, 'upper', 10, 1.0, AP, x, 1, 1.0, y, 1 ); // $ExpectError
	gspmv( null, 'upper', 10, 1.0, AP, x, 1, 1.0, y, 1 ); // $ExpectError
	gspmv( void 0, 'upper', 10, 1.0, AP, x, 1, 1.0, y, 1 ); // $ExpectError
	gspmv( [], 'upper', 10, 1.0, AP, x, 1, 1.0, y, 1 ); // $ExpectError
	gspmv( {}, 'upper', 10, 1.0, AP, x, 1, 1.0, y, 1 ); // $ExpectError
	gspmv( ( x: number ): number => x, 'upper', 10, 1.0, AP, x, 1, 1.0, y, 1 ); // $ExpectError
}

