	gspmv( 'row-major', void 0, 10, 1.0, AP, x, 1, 1.0, y, 1 ); // $ExpectError
	gspmv( 'row-major', [ '1' ], 10, 1.0, AP, x, 1, 1.0, y, 1 ); // $ExpectError
	gspmv( 'row-major', {}, 10, 1.0, AP, x, 1, 1.0, y, 1 ); // $ExpectError
	gspmv( 'row-major', ( x: number ): number => x, 10, 1.0, AP, x, 1, 1.0, y, 1 ); // $ExpectError
