// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Float64Array( 10 );
	const y = new Float64Array( 10 );
	const AP = new Float64Array( 55 );

	gspmv(); // $ExpectError
	gspmv( 'row-major' ); // $ExpectError
	gspmv( 'row-major', 'upper' ); // $ExpectError
	gspmv( 'row-major', 'upper', 10 ); // $ExpectError
	gspmv( 'row-major', 'upper', 10, 1.0 ); // $ExpectError
	gspmv( 'row-major', 'upper', 10, 1.0, AP ); // $ExpectError
	gspmv( 'row-major', 'upper', 10, 1.0, AP, x ); // $ExpectError
	gspmv( 'row-major', 'upper', 10, 1.0, AP, x, 1 ); // $ExpectError
	gspmv( 'row-major', 'upper', 10, 1.0, AP, x, 1, 1.0 ); // $ExpectError
	gspmv( 'row-major', 'upper', 10, 1.0, AP, x, 1, 1.0, y ); // $ExpectError
	gspmv( 'row-major', 'upper', 10, 1.0, AP, x, 1, 1.0, y, 1, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns an array...
