// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const x = new Float64Array( 10 );
	const y = new Float64Array( 10 );
	const AP = new Float64Array( 55 );

	gspmv.ndarray(); // $ExpectError
	gspmv.ndarray( 'row-major' ); // $ExpectError
	gspmv.ndarray( 'row-major', 'upper' ); // $ExpectError
	gspmv.ndarray( 'row-major', 'upper', 10 ); // $ExpectError
	gspmv.ndarray( 'row-major', 'upper', 10, 1.0 ); // $ExpectError
	gspmv.ndarray( 'row-major', 'upper', 10, 1.0, AP ); // $ExpectError
	gspmv.ndarray( 'row-major', 'upper', 10, 1.0, AP, 0 ); // $ExpectError
	gspmv.ndarray( 'row-major', 'upper', 10, 1.0, AP, 0, x ); // $ExpectError
	gspmv.ndarray( 'row-major', 'upper', 10, 1.0, AP, 0, x, 1 ); // $ExpectError
	gspmv.ndarray( 'row-major', 'upper', 10, 1.0, AP, 0, x, 1, 0 ); // $ExpectError
	gspmv.ndarray( 'row-major', 'upper', 10, 1.0, AP, 0, x, 1, 0, 1.0 ); // $ExpectError
	gspmv.ndarray( 'row-major', 'upper', 10, 1.0, AP, 0, x, 1, 0, 1.0, y ); // $ExpectError
	gspmv.ndarray( 'row-major', 'upper', 10, 1.0, AP, 0, x, 1, 0, 1.0, y, 1 ); // $ExpectError
	gspmv.ndarray( 'row-major', 'upper', 10, 1.0, AP, 0, x, 1, 0, 1.0, y, 1, 0, 10 ); // $ExpectError
}
